<?php
require __DIR__.'/config.php'; require_role(['admin','teacher']);$u=current_user();$teachers=read_json('teachers');$classes=read_json('classes');$students=read_json('students');
$tid=(int)($_GET['teacher_id']??0);if($u['role']==='teacher'){foreach($teachers as $t)if(strtolower($t['email']??'')===strtolower($u['username']))$tid=(int)$t['id'];}
$mine=array_values(array_filter($classes,fn($c)=>$u['role']==='admin'||(int)($c['teacher_id']??0)===$tid));$ids=array_map(fn($c)=>(int)$c['id'],$mine);$roster=array_values(array_filter($students,fn($s)=>in_array((int)($s['class_id']??0),$ids,true)));
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Roster — Ridgefield</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1100px;margin:auto;padding:30px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #e2e6e2;text-align:left}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{padding:18px;background:#f3f5f1;border:1px solid #dde2dd}@media(max-width:800px){.cards{grid-template-columns:1fr}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="school.php">← School Management</a></p><h1>Teacher Roster</h1><p>Classes assigned to your teaching profile.</p><div class="cards"><?php foreach($mine as $c):?><div class="card"><strong><?=h($c['name']??'')?></strong><br>Grade <?=h($c['grade']??'')?> · <?=h($c['year']??'')?></div><?php endforeach;?></div><h2>Learners</h2><table class="table"><tr><th>Student</th><th>Student No.</th><th>Grade</th><th>Profile</th></tr><?php foreach($roster as $st):?><tr><td><?=h($st['name']??'')?></td><td><?=h($st['student_no']??'')?></td><td><?=h($st['grade']??'')?></td><td><a href="../portal/profile.php?student_id=<?=h((string)$st['id'])?>">View profile</a> · <a href="../portal/report.php?student_id=<?=h((string)$st['id'])?>">Report</a></td></tr><?php endforeach;if(!$roster):?><tr><td colspan="4">No learners are assigned.</td></tr><?php endif;?></table></div><script src="assets/dynamic-site.js"></script>
</body></html>